#!/usr/bin/env bash
#
# Builds and runs the host test suites, with no board involved. The Bash twin
# of tools/run_host_tests.ps1, for Linux and the CI container: the same
# suites in the same order, the same compiler flags.
#
# components/satlink has no ESP-IDF dependencies precisely so that this is
# possible: framing bugs are far cheaper to find in a terminal than over a UART.
# The BTA, cover and LHDC replays need components/bt generated by tools/setup.sh.
#
#   CC=gcc PYTHON=python3 tools/run_host_tests.sh
#
# Windows Git Bash with MSYS2: CC=C:/msys64/ucrt64/bin/gcc.exe PYTHON=python

set -euo pipefail

repo=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cc=${CC:-gcc}
python=${PYTHON:-python3}
out="$repo/build/host"
mkdir -p "$out"

command -v "$cc" >/dev/null 2>&1 || { echo "run_host_tests: no C compiler at $cc. Set CC." >&2; exit 1; }
# A MSYS2 gcc cannot find its own cc1 unless its directory is on PATH, and it
# fails with no message at all. On Git Bash the directory has to be in POSIX
# form to count; the Python scripts still get the path as given.
case "$cc" in
    */*)
        cc_dir=$(dirname "$cc")
        if command -v cygpath >/dev/null 2>&1; then cc_dir=$(cygpath -u "$cc_dir"); fi
        PATH="$cc_dir:$PATH"; export PATH;;
esac

sources=(
    "$repo/tests/host/main.c"
    "$repo/tests/host/test_format_sync.c"
    "$repo/tests/host/test_satlink.c"
    "$repo/tests/host/test_messages.c"
    "$repo/tests/host/test_golden.c"
    "$repo/components/satlink/cobs.c"
    "$repo/components/satlink/crc16.c"
    "$repo/components/satlink/frame.c"
    "$repo/components/satlink/codec.c"
    "$repo/components/satlink/messages.c"
)
cflags=(-std=c17 -Wall -Wextra -Werror -g -O1
        "-I$repo/components/satlink/include" "-I$repo/tests/host")

# The undefined-behaviour sanitizer is worth having and not worth requiring.
echo 'int main(void){return 0;}' > "$out/ubsan_probe.c"
if "$cc" -fsanitize=undefined "$out/ubsan_probe.c" -o "$out/ubsan_probe" >/dev/null 2>&1; then
    cflags+=(-fsanitize=undefined -fno-sanitize-recover=all)
else
    echo 'run_host_tests: no libubsan here, running without the sanitizer.'
fi

"$cc" "${cflags[@]}" "${sources[@]}" -o "$out/test_satlink"
"$out/test_satlink"

# The endpoint re-registration machine, pure C out of main/.
"$cc" -std=c17 -Wall -Wextra -Werror -g -O1 \
    "-I$repo/main" "-I$repo/components/satlink/include" "-I$repo/tests/host" \
    "$repo/tests/host/test_endpoints.c" -o "$out/test_endpoints"
"$out/test_endpoints"

# Protocol 1.8 on the device side: settings, bonds, pairing, reconnect. Pure C too.
"$cc" -std=c17 -Wall -Wextra -Werror -g -O1 \
    "-I$repo/main" "-I$repo/components/satlink/include" "-I$repo/tests/host" \
    "$repo/tests/host/test_bt_settings.c" -o "$out/test_bt_settings"
"$out/test_bt_settings"

# Replay the codec-switch race through source extracted from our generated BT.
"$python" "$repo/tools/run_bta_reopen_tests.py" --cc "$cc"
# A live PING/PONG link must recover a dropped startup capability greeting.
"$python" "$repo/tools/run_hello_tests.py" --cc "$cc"
# Cover streaming must survive queue refusals and cancel delayed OBEX pulls.
"$python" "$repo/tools/run_cover_tests.py" --cc "$cc"
"$python" "$repo/tools/run_lhdc_tests.py" --cc "$cc"
